const kb = JSON.parse(data.knowledge_base);
const query = data.transcript.toLowerCase();
const query_words = query.split(/\s+/).filter(w => w.length > 3);

// Score FAQs by keyword overlap
const scored = [];
for (const faq of kb.faqs) {
  let score = 0;
  const faq_text = (faq.question + ' ' + faq.answer).toLowerCase();

  for (const word of query_words) {
    if (faq_text.includes(word)) {
      score++;
    }
  }

  scored.push({ score: score, faq: faq });
}

// Sort by score, get top 2
scored.sort((a, b) => b.score - a.score);
const top_faqs = scored.slice(0, 2);

// Format as context for Claude
const context = top_faqs
  .map(item => `Q: ${item.faq.question}\nA: ${item.faq.answer}`)
  .join('\n\n');

return {
  kb_context: context,
  top_faqs_count: top_faqs.length,
  total_faqs_available: kb.faqs.length,
  transcript: data.transcript,
  turn_number: data.turn_number || 1,
  language: data.language || 'en'
};

// Parse Claude response
const response_text = data.content?.[0]?.text || data.body?.content?.[0]?.text || '';

return {
  response: response_text,
  transcript: data.transcript,
  turn_number: data.turn_number || 1,
  language: data.language || 'en',
  kb_context_count: data.top_faqs_count || 2
};
